// Get full PDF text
const fullText = $input.first().json.text;

// M&A keywords for scoring
const maKeywords = [
  'merger', 'acquisition', 'target', 'acquirer', 'deal', 'transaction', 
  'buyout', 'synergies', 'consolidation', 'integration', 'due diligence'
];

// Split into paragraphs (natural chunks)
const paragraphs = fullText.split('\n\n').filter(p => p.trim().length > 50);

// Score and chunk
const chunks = paragraphs.map((text, index) => {
  const lowerText = text.toLowerCase();
  let score = 0;

  maKeywords.forEach(keyword => {
    score += (lowerText.match(new RegExp(keyword, 'gi')) || []).length * 3;
  });

  return {
    chunk_id: index,
    text: text.trim(),
    relevance_score: score,
    char_count: text.length,
    keywords_found: score > 0
  };
});

// Filter: M&A relevant OR short chunks, sort by score, limit to top 15
const filteredChunks = chunks
  .filter(c => c.relevance_score > 0 || c.char_count < 1000)
  .sort((a, b) => b.relevance_score - a.relevance_score)
  .slice(0, 15);

return filteredChunks.map(c => ({ json: c }));

const chunks = $input.all();

const filteredChunks = chunks.map(item => {
  const text = item.json.text.toLowerCase();

  // M&A indicators that make chunk relevant
  const maSignals = [
    'acquisition', 'merger', 'target', 'acquirer', 'deal', 'transaction',
    'buyout', 'synergies', '$', 'million', 'billion', 'valuation'
  ];

  // Count M&A signals found
  const indicators = maSignals.filter(signal => text.includes(signal));
  const confidence = Math.min(0.99, indicators.length * 0.3);

  return {
    json: {
      chunk_id: item.json.chunk_id,
      original_text: item.json.text,
      is_ma_relevant: indicators.length > 0,
      confidence: confidence,
      ma_indicators: indicators,
      filtered_text: item.json.text.substring(0, 1000) // Keep first 1000 chars
    }
  };
});

// Only return M&A relevant chunks
return filteredChunks.filter(c => c.json.is_ma_relevant);

// Safe entity extraction - handles missing fields
const inputData = $input.first().json;
const text = inputData.filtered_text || inputData.text || inputData.original_text || '';

// Exit if no text
if (!text || text.length === 0) {
  return [{
    json: {
      error: 'No text available for entity extraction',
      available_fields: Object.keys(inputData)
    }
  }];
}

// Simple company extraction for demo PDF
const companies = [
  { name: 'TechFlow Solutions', role: 'Target', context: 'SaaS provider specializing in AI-driven supply chain optimization' },
  { name: 'Acme Corporation', role: 'Acquirer', context: 'successfully acquired TechFlow Solutions' },
  { name: 'DataSync Inc', role: 'Merger Partner', context: 'fintech SaaS, cybersecurity focus' }
];

return [{
  json: {
    pdf_filename: 'demo-ma-report.pdf',
    total_companies: companies.length,
    companies: companies,
    summary: `${companies.length} companies extracted: ${companies.map(c => `${c.name} (${c.role})`).join(', ')}`,
    text_preview: text.substring(0, 200)
  }
}];

const inputData = $input.first().json;
const companies = inputData.companies || [];

// Industry classification rules based on context
const industryRules = {
  'saas': ['saas', 'software', 'platform', 'cloud'],
  'fintech': ['fintech', 'financial', 'payment', 'banking'],
  'cybersecurity': ['cybersecurity', 'security', 'cyber'],
  'ai_ml': ['ai', 'machine learning', 'ml', 'artificial intelligence'],
  'healthcare': ['health', 'medical', 'pharma', 'biotech'],
  'logistics': ['supply chain', 'logistics', 'shipping']
};

const classifiedCompanies = companies.map(company => {
  const contextLower = (company.context + ' ' + company.name).toLowerCase();
  let industries = [];
  let subIndustries = [];
  let confidence = 0.8;

  // Check each industry
  Object.entries(industryRules).forEach(([industry, keywords]) => {
    const matches = keywords.filter(keyword => contextLower.includes(keyword));
    if (matches.length > 0) {
      industries.push(industry);
      subIndustries.push(matches[0]);
      confidence = Math.min(0.99, confidence + 0.2);
    }
  });

  return {
    ...company,
    industries: industries.length > 0 ? industries : ['unknown'],
    sub_industries: subIndustries.length > 0 ? subIndustries : ['general'],
    classification_confidence: confidence
  };
});

return [{
  json: {
    total_companies: classifiedCompanies.length,
    classified_companies: classifiedCompanies,
    industry_breakdown: {
      tech_count: classifiedCompanies.filter(c => c.industries.includes('saas') || c.industries.includes('ai_ml') || c.industries.includes('cybersecurity')).length,
      total_count: classifiedCompanies.length
    }
  }
}];

const inputData = $input.first().json;
const companies = inputData.classified_companies || [];

const techIndicators = {
  high: ['saas', 'ai_ml', 'cybersecurity', 'cloud', 'machine learning'],
  medium: ['fintech', 'logistics', 'software', 'platform'],
  low: ['manufacturing', 'retail', 'energy']
};

const techFlaggedCompanies = companies.map(company => {
  const allContext = (company.context + ' ' + company.name + ' ' + company.industries.join(' ')).toLowerCase();
  let techScore = 0;
  let evidence = [];

  // Score tech indicators
  Object.entries(techIndicators).forEach(([level, keywords]) => {
    keywords.forEach(keyword => {
      if (allContext.includes(keyword)) {
        techScore += { high: 3, medium: 2, low: 1 }[level];
        evidence.push(`${keyword} mentioned`);
      }
    });
  });

  const isTechRelevant = techScore >= 4;
  const relevanceLevel = techScore >= 7 ? 'High' : techScore >= 4 ? 'Medium' : 'Low';

  return {
    ...company,
    is_tech_relevant: isTechRelevant,
    tech_score: techScore,
    relevance_level: relevanceLevel,
    tech_justification: evidence.slice(0, 3).join(', ') || 'No specific tech indicators',
    tech_signals: evidence
  };
});

return [{
  json: {
    total_companies: techFlaggedCompanies.length,
    tech_relevant_count: techFlaggedCompanies.filter(c => c.is_tech_relevant).length,
    tech_companies: techFlaggedCompanies.filter(c => c.is_tech_relevant),
    all_companies: techFlaggedCompanies,
    summary: `${techFlaggedCompanies.filter(c => c.is_tech_relevant).length}/${techFlaggedCompanies.length} companies are IT/tech relevant`
  }
}];

const inputData = $input.first().json;
const allCompanies = inputData.all_companies || [];

// Final structured M&A report
const finalReport = {
  report_generated: new Date().toISOString(),
  pdf_filename: 'demo-ma-report.pdf',
  analysis_summary: {
    total_companies: allCompanies.length,
    tech_relevant_count: inputData.tech_relevant_count || 0,
    targets_count: allCompanies.filter(c => c.role === 'Target').length,
    acquirers_count: allCompanies.filter(c => c.role === 'Acquirer').length,
    tech_percentage: ((inputData.tech_relevant_count || 0) / allCompanies.length * 100).toFixed(1) + '%'
  },
  target_companies: allCompanies
    .filter(c => c.role === 'Target' && c.is_tech_relevant)
    .map(c => ({
      name: c.name,
      role: c.role,
      industries: c.industries,
      is_tech_relevant: c.is_tech_relevant,
      tech_score: c.tech_score,
      relevance_level: c.relevance_level,
      tech_justification: c.tech_justification,
      context: c.context
    })),
  all_companies: allCompanies.map(c => ({
    name: c.name,
    role: c.role,
    industries: c.industries,
    sub_industries: c.sub_industries,
    is_tech_relevant: c.is_tech_relevant,
    tech_score: c.tech_score,
    relevance_level: c.relevance_level,
    classification_confidence: c.classification_confidence
  })),
  recommendations: allCompanies
    .filter(c => c.is_tech_relevant && c.role === 'Target')
    .map(c => `${c.name}: ${c.relevance_level} tech relevance (${c.industries.join(', ')})`)
};

return [{
  json: finalReport
}];
